        public static readonly Dictionary<string, Dictionary<string, string>> Loc = new Dictionary<string, Dictionary<string, string>>
        {
                ["de-DE"] = new Dictionary<string, string> { ["ui.noticeAsk"]="Möchtest du die Fahrzeuganzahl lieber selbst festlegen? Für die meisten ist das nicht nötig: Wenn der Mod es übernimmt, bleibt der Fahrplan ehrlich.", ["opt.VehicleCounts.L"]="Verwaltung der Fahrzeuganzahl", ["opt.VehicleCounts.D"]="Wer entscheidet, wie viele Fahrzeuge auf jeder Linie mit Fahrplan fahren. \"Der Mod entscheidet\" bemisst jede Linie an ihrer gemessenen Umlaufzeit, damit sie den eingestellten Takt tatsächlich halten kann; das ist die empfohlene Einstellung und erfordert keine Aufmerksamkeit. \"Ein anderer Mod entscheidet\" lässt die Fahrzeuganzahl vollständig unangetastet, sodass ein spezialisierter Fuhrpark-Mod sie übernehmen kann, ohne dass beide um dieselbe Einstellung streiten. \"Ich entscheide, pro Linie\" lässt dich die Anzahl selbst eintragen; jede Linie, die du nicht eingestellt hast, wird weiterhin vom Mod bemessen. Das Halten bis zur Abfahrtszeit funktioniert in allen drei Fällen genau gleich.", ["enum.VehicleCounts.ModManages"]="Der Mod entscheidet", ["enum.VehicleCounts.OtherModManages"]="Ein anderer Mod entscheidet", ["enum.VehicleCounts.PlayerManages"]="Ich entscheide, pro Linie", ["ui.noticeTitle"]="Die Fahrzeuganzahl ändert sich", ["ui.noticeBody"]="Dieser Mod bemisst jede Linie, indem er misst, wie lange ihre Route wirklich dauert. Die spieleigene Fahrzeitschätzung liegt deutlich darunter, sodass eine nach der Schätzung bemessene Linie weniger Fahrzeuge einsetzt, als dein gewählter Takt benötigt. Echtes Messen bedeutet also mehr Fahrzeuge, als die Schätzung ergeben würde. Ihr Betrieb kostet nichts, aber jedes Depot fasst nur etwa zehn, achte daher auf Warnungen wegen fehlender Fahrzeuge. Wenn eine Linie mehr verlangt, als du möchtest, vergrößere ihren Takt.", ["ui.noticeWhere"]="Du kannst dies jederzeit in den Optionen unter \"Verwaltung der Fahrzeuganzahl\" ändern.", ["ui.noticeKeep"]="Nein, der Mod soll sie verwalten", ["ui.noticeOff"]="Ja, ich verwalte sie selbst", ["opt.StopAtEveryStop.L"]="An jeder Haltestelle halten (auch an leeren)", ["opt.StopAtEveryStop.D"]="Standardmäßig lässt Cities: Skylines II einen Bus eine Haltestelle ÜBERSPRINGEN, an der niemand wartet und niemand aussteigen will — er bremst nur ab und rollt durch, sodass diese Haltestelle nie bis zur planmäßigen Abfahrt gehalten wird und der Bus seinem Fahrplan vorauslaufen kann. Die Endhaltestelle wird nun unabhängig von dieser Einstellung immer zum Halten gezwungen (sie zu überspringen würde den ganzen Fahrplan sprengen). Aktiviere dies, um Busse zu zwingen, an JEDER Haltestelle einer getakteten Linie zu halten, sodass jede angezeigte Zeit eingehalten wird — auf Kosten einer kurzen Standzeit an jeder leeren Haltestelle, die Linien etwas langsamer macht. Betrifft nur Busse und andere Straßenfahrzeuge; Züge, Straßenbahnen, Schiffe und Flugzeuge halten bereits an jeder Station. Standardmäßig AUS.", ["opt.RealisticTripsCompat.L"]="Realistic Trips / Zeitlupen-Kompatibilität — AN, wenn du RT oder Time2Work nutzt (ALPHA)", ["opt.RealisticTripsCompat.D"]="Standardmäßig AUS — lass es aus, außer du nutzt einen Mod, der den Spieltag verlängert (Time2Work / \"Realistic Trips\" oder ähnlich). Aktiviere es mit einem solchen Mod, und Abfahrten, Haltezeiten und Flottengrößen bleiben korrekt, statt zu früh zu laufen; der Mod misst die echte Taglänge automatisch. Ohne Zeitlupen-Mod bewirkt diese Einstellung nichts, und erkennt der Mod einen solchen, während dies AUS ist, vermerkt er es im Log. HINWEIS: Dieser Kompatibilitätspfad ist ALPHA und wurde noch NICHT im Spiel mit Realistic Trips getestet — bitte melde alles Auffällige. Unter Realistic Trips nutzen deine Linien korrekterweise weniger Fahrzeuge als zuvor.", ["opt.MorningPeakStart.L"]="Beginn der Morgenspitze", ["opt.MorningPeakStart.D"]="Stunde, zu der die morgendliche Hauptverkehrszeit beginnt.", ["opt.MorningPeakEnd.L"]="Ende der Morgenspitze", ["opt.MorningPeakEnd.D"]="Stunde, zu der die morgendliche Hauptverkehrszeit endet.", ["opt.EveningPeakStart.L"]="Beginn der Abendspitze", ["opt.EveningPeakStart.D"]="Stunde, zu der die abendliche Hauptverkehrszeit beginnt.", ["opt.EveningPeakEnd.L"]="Ende der Abendspitze", ["opt.EveningPeakEnd.D"]="Stunde, zu der die abendliche Hauptverkehrszeit endet.", ["opt.NightStart.L"]="Nachtbeginn", ["opt.NightStart.D"]="Stunde, zu der der Nachtbetrieb beginnt (kann über Mitternacht hinausgehen).", ["opt.NightEnd.L"]="Nachtende", ["opt.NightEnd.D"]="Stunde, zu der der Nachtbetrieb endet.", ["opt.Enabled.L"]="TransitTimetables aktivieren", ["opt.Enabled.D"]="Hauptschalter für den gesamten Mod. Aus = exakt Vanilla: jede Linie wird nicht mehr verwaltet (gehaltene Busse werden freigegeben und die vom Mod gesetzte Fahrzeuganzahl sowie der Entklumpungsfaktor werden zurückgesetzt), während deine linienbezogenen Fahrpläne erhalten bleiben, sodass ein erneutes Aktivieren sie fortsetzt. Standardmäßig AN.", ["grp.GroupWindows"]="Hauptverkehrszeiten", ["grp.GroupCompat"]="Kompatibilität", ["grp.GroupStops"]="Haltestellen", ["grp.GroupGeneral"]="Allgemein", ["ui.to"]="bis", ["ui.timetable"]="FAHRPLAN", ["ui.on"]="AN", ["ui.off"]="AUS", ["ui.ttNow"]="jetzt alle {i} Min · {f} Fahrzeuge", ["ui.ttNext"]="nächste: {n}", ["ui.firstDeparture"]="Erste Abfahrt", ["ui.peakInterval"]="Spitze", ["ui.offPeakInterval"]="Nebenzeit", ["ui.otherHours"]="übrige Stunden", ["ui.nightInterval"]="Nacht", ["ui.customLinePeak"]="Eigene Spitze (diese Linie)", ["ui.morningPeak"]="Morgenspitze", ["ui.eveningPeak"]="Abendspitze", ["ui.customPeakInterval"]="Eigenes Spitzenintervall", ["ui.terminusHint"]="Wähle eine Haltestelle, um ihre Abfahrten zu sehen und sie als Endhaltestelle dieser Linie festzulegen.", ["ui.noLines"]="Keine Linien bedienen diese Haltestelle.", ["ui.line"]="Linie {n}", ["ui.terminusBadge"]="Endhaltestelle", ["ui.departs"]="Abfahrt: {d}", ["ui.noDepartures"]="keine Abfahrten geplant", ["ui.notTimetabled"]="kein Fahrplan", ["ui.estimatedTimes"]="geschätzt, noch nicht gemessen", ["ui.setTerminusThis"]="Als Endhaltestelle festlegen", ["ui.setTerminusAll"]="Als Endhaltestelle für alle Linien hier festlegen", ["ui.setTerminusHint"]="Die Endhaltestelle verankert den Fahrplan und den Fahrzeughalt; Busse werden hier ausgemustert.", ["ui.buttonTooltip"]="Transit Timetables", ["ui.panelTitle"]="ABFAHRTEN", ["ui.panelHint"]="Wähle eine Haltestelle, um die Abfahrten jeder Linie von dort zu sehen. Um den Fahrplan einer Linie zu bearbeiten, wähle die Linie — ihre Steuerung befindet sich im Infofenster der Linie.", },
                ["es-ES"] = new Dictionary<string, string> { ["ui.noticeAsk"]="¿Prefieres fijar tú mismo el número de vehículos? La mayoría no debería: dejar que lo haga el mod es lo que mantiene el horario realista.", ["opt.VehicleCounts.L"]="Gestión del número de vehículos", ["opt.VehicleCounts.D"]="Quién decide cuántos vehículos circulan en cada línea con horario. \"Lo decide el mod\" dimensiona cada línea según su tiempo de vuelta medido para que pueda mantener realmente el intervalo que has fijado; es la opción recomendada y no requiere atención. \"Lo decide otro mod\" deja el número de vehículos completamente intacto, de modo que un mod de flotas dedicado pueda gestionarlo sin que ambos entren en conflicto. \"Lo decido yo, por línea\" te permite introducir las cantidades tú mismo; cualquier línea que no hayas configurado la sigue dimensionando el mod. Las esperas de salida funcionan igual en los tres casos.", ["enum.VehicleCounts.ModManages"]="Lo decide el mod", ["enum.VehicleCounts.OtherModManages"]="Lo decide otro mod", ["enum.VehicleCounts.PlayerManages"]="Lo decido yo, por línea", ["ui.noticeTitle"]="El número de vehículos va a cambiar", ["ui.noticeBody"]="Este mod dimensiona cada línea midiendo cuánto tarda realmente su recorrido. La estimación de tiempo de viaje del propio juego se queda muy por debajo, así que una línea dimensionada según la estimación circula con menos vehículos de los que necesita el intervalo que has elegido. Medir de verdad significa más vehículos de los que daría la estimación. No cuestan nada en mantenimiento, pero cada cochera solo alberga unos diez, así que vigila los avisos de vehículos insuficientes. Si una línea pide más de los que quieres, amplía su intervalo.", ["ui.noticeWhere"]="Puedes cambiarlo en cualquier momento en Opciones, en \"Gestión del número de vehículos\".", ["ui.noticeKeep"]="No, que lo gestione el mod", ["ui.noticeOff"]="Sí, lo gestionaré yo", ["opt.StopAtEveryStop.L"]="Parar en todas las paradas (incluso las vacías)", ["opt.StopAtEveryStop.D"]="Por defecto, Cities: Skylines II permite que un autobús OMITA una parada donde nadie espera y nadie quiere bajar: solo reduce la velocidad y pasa de largo, así que esa parada nunca se retiene hasta su salida programada y el autobús puede adelantarse a su horario. La terminal ahora siempre se fuerza a parar, independientemente de esta opción (omitirla dejaría colgado todo el horario). Activa esto para forzar a los autobuses a detenerse en TODAS las paradas de una línea con horario, de modo que se respeten todas las horas publicadas, a costa de una breve espera en cada parada vacía, lo que hace que las líneas vayan un poco más lentas. Afecta solo a autobuses y otros vehículos de carretera; trenes, tranvías, barcos y aviones ya paran en todas las estaciones. Desactivado por defecto.", ["opt.RealisticTripsCompat.L"]="Compatibilidad con Realistic Trips / tiempo lento — actívalo si usas RT o Time2Work (ALFA)", ["opt.RealisticTripsCompat.D"]="Desactivado por defecto: déjalo así salvo que uses un mod que alargue el día del juego (Time2Work / \"Realistic Trips\" o similar). Actívalo con un mod de ese tipo y las salidas, los horarios de parada y el tamaño de la flota seguirán siendo correctos en lugar de adelantarse; el mod mide automáticamente la duración real del día. Sin un mod de tiempo lento, esta opción no hace nada, y si el mod detecta uno mientras esto está desactivado lo anotará en el registro. NOTA: esta vía de compatibilidad es ALFA y AÚN NO se ha probado con Realistic Trips en el juego; informa de cualquier anomalía. Con Realistic Trips, tus líneas usarán correctamente menos vehículos que antes.", ["opt.MorningPeakStart.L"]="Inicio de la hora punta de la mañana", ["opt.MorningPeakStart.D"]="Hora en que empieza el nivel de servicio de la hora punta de la mañana.", ["opt.MorningPeakEnd.L"]="Fin de la hora punta de la mañana", ["opt.MorningPeakEnd.D"]="Hora en que termina el nivel de servicio de la hora punta de la mañana.", ["opt.EveningPeakStart.L"]="Inicio de la hora punta de la tarde", ["opt.EveningPeakStart.D"]="Hora en que empieza el nivel de servicio de la hora punta de la tarde.", ["opt.EveningPeakEnd.L"]="Fin de la hora punta de la tarde", ["opt.EveningPeakEnd.D"]="Hora en que termina el nivel de servicio de la hora punta de la tarde.", ["opt.NightStart.L"]="Inicio de la noche", ["opt.NightStart.D"]="Hora en que empieza el servicio nocturno (puede pasar de la medianoche).", ["opt.NightEnd.L"]="Fin de la noche", ["opt.NightEnd.D"]="Hora en que termina el servicio nocturno.", ["opt.Enabled.L"]="Activar TransitTimetables", ["opt.Enabled.D"]="Interruptor principal de todo el mod. Desactivado = vanilla exacto: todas las líneas dejan de gestionarse (los autobuses retenidos se liberan y se revierten el recuento de flota y el factor de dispersión aplicados por el mod), mientras que tus horarios por línea se conservan para que reactivarlo los reanude. Activado por defecto.", ["grp.GroupWindows"]="Franjas de hora punta", ["grp.GroupCompat"]="Compatibilidad", ["grp.GroupStops"]="Paradas", ["grp.GroupGeneral"]="General", ["ui.to"]="a", ["ui.timetable"]="HORARIO", ["ui.on"]="SÍ", ["ui.off"]="NO", ["ui.ttNow"]="ahora cada {i} min · {f} vehículos", ["ui.ttNext"]="siguiente: {n}", ["ui.firstDeparture"]="Primera salida", ["ui.peakInterval"]="Hora punta", ["ui.offPeakInterval"]="Fuera de punta", ["ui.otherHours"]="otras horas", ["ui.nightInterval"]="Noche", ["ui.customLinePeak"]="Hora punta personalizada (esta línea)", ["ui.morningPeak"]="Hora punta de la mañana", ["ui.eveningPeak"]="Hora punta de la tarde", ["ui.customPeakInterval"]="Intervalo de hora punta personalizado", ["ui.terminusHint"]="Selecciona una parada para ver sus salidas y fijarla como terminal de esta línea.", ["ui.noLines"]="Ninguna línea da servicio a esta parada.", ["ui.line"]="Línea {n}", ["ui.terminusBadge"]="terminal", ["ui.departs"]="sale: {d}", ["ui.noDepartures"]="sin salidas programadas", ["ui.notTimetabled"]="sin horario", ["ui.estimatedTimes"]="estimado, aún sin medir", ["ui.setTerminusThis"]="Fijar como terminal", ["ui.setTerminusAll"]="Fijar como terminal para todas las líneas de aquí", ["ui.setTerminusHint"]="La terminal ancla el horario y la retención de vehículos; los autobuses se retiran aquí.", ["ui.buttonTooltip"]="Horarios de transporte", ["ui.panelTitle"]="SALIDAS", ["ui.panelHint"]="Selecciona una parada para ver las salidas de todas las líneas desde ella. Para editar el horario de una línea, selecciona la línea: sus controles están en el panel de información de la línea.", },
                ["fr-FR"] = new Dictionary<string, string> { ["ui.noticeAsk"]="Préférez-vous définir vous-même le nombre de véhicules ? Ce n'est pas conseillé pour la plupart des joueurs : laisser le mod s'en charger est ce qui garde l'horaire honnête.", ["opt.VehicleCounts.L"]="Gestion du nombre de véhicules", ["opt.VehicleCounts.D"]="Qui décide du nombre de véhicules de chaque ligne avec horaires. \"Le mod décide\" dimensionne chaque ligne d'après sa durée de boucle mesurée afin qu'elle puisse réellement tenir l'intervalle que vous avez fixé ; c'est le réglage recommandé et il ne demande aucune attention. \"Un autre mod décide\" laisse le nombre de véhicules totalement intact, pour qu'un mod de flotte dédié puisse s'en charger sans que les deux se disputent le même réglage. \"Je décide, ligne par ligne\" vous laisse saisir vous-même les effectifs ; toute ligne que vous n'avez pas réglée reste dimensionnée par le mod. L'attente au départ fonctionne de la même façon dans les trois cas.", ["enum.VehicleCounts.ModManages"]="Le mod décide", ["enum.VehicleCounts.OtherModManages"]="Un autre mod décide", ["enum.VehicleCounts.PlayerManages"]="Je décide, ligne par ligne", ["ui.noticeTitle"]="Le nombre de véhicules va changer", ["ui.noticeBody"]="Ce mod dimensionne chaque ligne en mesurant la durée réelle de son parcours. L'estimation de temps de trajet du jeu est très inférieure, si bien qu'une ligne dimensionnée d'après elle circule avec moins de véhicules que ne l'exige l'intervalle choisi. Mesurer réellement signifie donc plus de véhicules que ne le donnerait l'estimation. Ils ne coûtent rien à exploiter, mais chaque dépôt n'en accueille qu'une dizaine, surveillez donc les avertissements de véhicules insuffisants. Si une ligne en demande plus que vous ne le souhaitez, élargissez son intervalle.", ["ui.noticeWhere"]="Vous pouvez changer cela à tout moment dans les Options, sous \"Gestion du nombre de véhicules\".", ["ui.noticeKeep"]="Non, laisser le mod les gérer", ["ui.noticeOff"]="Oui, je m'en occupe", ["opt.StopAtEveryStop.L"]="S'arrêter à chaque arrêt (même vides)", ["opt.StopAtEveryStop.D"]="Par défaut, Cities: Skylines II autorise un bus à SAUTER un arrêt où personne n'attend et personne ne veut descendre — il ne fait que ralentir et passer, si bien que cet arrêt n'est jamais retenu jusqu'à son départ prévu et que le bus peut prendre de l'avance sur son horaire. Le terminus est désormais toujours forcé à s'arrêter quel que soit ce réglage (le sauter désorganiserait tout l'horaire). Activez cette option pour forcer les bus à s'arrêter à CHAQUE arrêt d'une ligne à horaire, afin que chaque horaire affiché soit respecté — au prix d'un court arrêt à chaque arrêt vide, ce qui ralentit un peu les lignes. Concerne uniquement les bus et autres véhicules routiers ; les trains, tramways, navires et avions s'arrêtent déjà à chaque station. Désactivé par défaut.", ["opt.RealisticTripsCompat.L"]="Compatibilité Realistic Trips / temps ralenti — activez si vous utilisez RT ou Time2Work (ALPHA)", ["opt.RealisticTripsCompat.D"]="Désactivé par défaut — laissez-le désactivé sauf si vous utilisez un mod qui allonge la journée en jeu (Time2Work / \\\"Realistic Trips\\\" ou similaire). Activez-le avec un tel mod et les départs, horaires d'arrêt et tailles de flotte restent corrects au lieu d'être en avance ; le mod mesure automatiquement la durée réelle de la journée. Sans mod de temps ralenti ce réglage ne fait rien, et si le mod en détecte un alors que ceci est désactivé il le signalera dans le journal. NOTE : ce chemin de compatibilité est en ALPHA et n'a PAS encore été testé en jeu avec Realistic Trips — merci de signaler tout comportement étrange. Sous Realistic Trips vos lignes utiliseront correctement moins de véhicules qu'auparavant.", ["opt.MorningPeakStart.L"]="Début de la pointe du matin", ["opt.MorningPeakStart.D"]="Heure à laquelle commence le niveau de service de pointe du matin.", ["opt.MorningPeakEnd.L"]="Fin de la pointe du matin", ["opt.MorningPeakEnd.D"]="Heure à laquelle se termine le niveau de service de pointe du matin.", ["opt.EveningPeakStart.L"]="Début de la pointe du soir", ["opt.EveningPeakStart.D"]="Heure à laquelle commence le niveau de service de pointe du soir.", ["opt.EveningPeakEnd.L"]="Fin de la pointe du soir", ["opt.EveningPeakEnd.D"]="Heure à laquelle se termine le niveau de service de pointe du soir.", ["opt.NightStart.L"]="Début de nuit", ["opt.NightStart.D"]="Heure à laquelle commence le service de nuit (peut passer minuit).", ["opt.NightEnd.L"]="Fin de nuit", ["opt.NightEnd.D"]="Heure à laquelle se termine le service de nuit.", ["opt.Enabled.L"]="Activer TransitTimetables", ["opt.Enabled.D"]="Interrupteur principal de tout le mod. Désactivé = jeu de base exact : toutes les lignes cessent d'être gérées (les bus retenus sont libérés et le nombre de véhicules ainsi que le facteur de désengorgement appliqués par le mod sont rétablis), tandis que vos horaires par ligne sont conservés pour reprendre à la réactivation. Activé par défaut.", ["grp.GroupWindows"]="Plages de pointe", ["grp.GroupCompat"]="Compatibilité", ["grp.GroupStops"]="Arrêts", ["grp.GroupGeneral"]="Général", ["ui.to"]="à", ["ui.timetable"]="HORAIRE", ["ui.on"]="ACTIVÉ", ["ui.off"]="DÉSACTIVÉ", ["ui.ttNow"]="actuellement toutes les {i} min · {f} véhicules", ["ui.ttNext"]="suivant : {n}", ["ui.firstDeparture"]="Premier départ", ["ui.peakInterval"]="Pointe", ["ui.offPeakInterval"]="Heures creuses", ["ui.otherHours"]="autres heures", ["ui.nightInterval"]="Nuit", ["ui.customLinePeak"]="Pointe personnalisée (cette ligne)", ["ui.morningPeak"]="Pointe du matin", ["ui.eveningPeak"]="Pointe du soir", ["ui.customPeakInterval"]="Intervalle de pointe personnalisé", ["ui.terminusHint"]="Sélectionnez un arrêt pour voir ses départs et le définir comme terminus de cette ligne.", ["ui.noLines"]="Aucune ligne ne dessert cet arrêt.", ["ui.line"]="Ligne {n}", ["ui.terminusBadge"]="terminus", ["ui.departs"]="départ : {d}", ["ui.noDepartures"]="aucun départ prévu", ["ui.notTimetabled"]="sans horaire", ["ui.estimatedTimes"]="estimé, pas encore mesuré", ["ui.setTerminusThis"]="Définir comme terminus", ["ui.setTerminusAll"]="Définir comme terminus pour toutes les lignes ici", ["ui.setTerminusHint"]="Le terminus ancre l'horaire et la rétention des véhicules ; les bus sont retirés ici.", ["ui.buttonTooltip"]="Horaires de transport", ["ui.panelTitle"]="DÉPARTS", ["ui.panelHint"]="Sélectionnez un arrêt pour voir les départs de chaque ligne depuis cet arrêt. Pour modifier l'horaire d'une ligne, sélectionnez la ligne — ses réglages se trouvent dans le panneau d'informations de la ligne.", },
                ["it-IT"] = new Dictionary<string, string> { ["ui.noticeAsk"]="Preferisci impostare tu stesso il numero di veicoli? Per la maggior parte non è necessario: lasciarlo fare alla mod è ciò che mantiene l'orario realistico.", ["opt.VehicleCounts.L"]="Gestione del numero di veicoli", ["opt.VehicleCounts.D"]="Chi decide quanti veicoli circolano su ogni linea con orario. \"Decide la mod\" dimensiona ogni linea in base al giro misurato, così da poter rispettare davvero l'intervallo impostato; è l'impostazione consigliata e non richiede attenzione. \"Decide un'altra mod\" lascia il numero di veicoli del tutto intatto, così una mod dedicata alla flotta può gestirlo senza che le due entrino in conflitto. \"Decido io, per linea\" ti permette di inserire tu stesso i numeri; ogni linea che non hai impostato continua a essere dimensionata dalla mod. L'attesa alla partenza funziona allo stesso modo in tutti e tre i casi.", ["enum.VehicleCounts.ModManages"]="Decide la mod", ["enum.VehicleCounts.OtherModManages"]="Decide un'altra mod", ["enum.VehicleCounts.PlayerManages"]="Decido io, per linea", ["ui.noticeTitle"]="Il numero di veicoli sta per cambiare", ["ui.noticeBody"]="Questa mod dimensiona ogni linea misurando quanto dura davvero il suo percorso. La stima dei tempi di percorrenza del gioco è molto inferiore, quindi una linea dimensionata sulla stima circola con meno veicoli di quanti ne richieda l'intervallo scelto. Misurare davvero significa più veicoli di quanti ne darebbe la stima. Non costano nulla, ma ogni deposito ne ospita circa dieci, quindi tieni d'occhio gli avvisi di veicoli insufficienti. Se una linea ne chiede più di quanti ne desideri, allarga il suo intervallo.", ["ui.noticeWhere"]="Puoi cambiarlo in qualsiasi momento nelle Opzioni, alla voce \"Gestione del numero di veicoli\".", ["ui.noticeKeep"]="No, lascia gestire alla mod", ["ui.noticeOff"]="Sì, li gestisco io", ["opt.StopAtEveryStop.L"]="Ferma a ogni fermata (anche quelle vuote)", ["opt.StopAtEveryStop.D"]="Per impostazione predefinita Cities: Skylines II consente a un autobus di SALTARE una fermata dove nessuno è in attesa e nessuno vuole scendere — rallenta soltanto e prosegue, così quella fermata non viene mai trattenuta fino alla partenza programmata e l'autobus può portarsi in anticipo sull'orario. Il capolinea è ora sempre obbligato a fermarsi indipendentemente da questa impostazione (saltarlo comprometterebbe l'intero orario). Attiva questa opzione per obbligare gli autobus a fermarsi a OGNI fermata di una linea con orario, così ogni orario esposto viene rispettato — al prezzo di una breve sosta a ogni fermata vuota, che rende le linee un po' più lente. Riguarda solo autobus e altri veicoli su strada; treni, tram, navi e aerei si fermano già a ogni stazione. Disattivata per impostazione predefinita.", ["opt.RealisticTripsCompat.L"]="Compatibilità con Realistic Trips / tempo rallentato — attiva se usi RT o Time2Work (ALPHA)", ["opt.RealisticTripsCompat.D"]="Disattivata per impostazione predefinita — lasciala disattivata a meno che tu non usi una mod che allunga la giornata di gioco (Time2Work / \\\"Realistic Trips\\\" o simili). Attivala con una mod di questo tipo e le partenze, gli orari di fermata e le dimensioni della flotta restano corretti anziché anticipare; la mod misura automaticamente la durata reale della giornata. Senza una mod di tempo rallentato questa impostazione non fa nulla, e se la mod ne rileva una mentre è disattivata lo segnalerà nel log. NOTA: questo percorso di compatibilità è in fase ALPHA e NON è ancora stato testato in gioco con Realistic Trips — segnala qualunque anomalia. Con Realistic Trips le tue linee useranno correttamente meno veicoli rispetto a prima.", ["opt.MorningPeakStart.L"]="Inizio picco mattutino", ["opt.MorningPeakStart.D"]="Ora in cui inizia il livello di servizio di picco mattutino.", ["opt.MorningPeakEnd.L"]="Fine picco mattutino", ["opt.MorningPeakEnd.D"]="Ora in cui termina il livello di servizio di picco mattutino.", ["opt.EveningPeakStart.L"]="Inizio picco serale", ["opt.EveningPeakStart.D"]="Ora in cui inizia il livello di servizio di picco serale.", ["opt.EveningPeakEnd.L"]="Fine picco serale", ["opt.EveningPeakEnd.D"]="Ora in cui termina il livello di servizio di picco serale.", ["opt.NightStart.L"]="Inizio notte", ["opt.NightStart.D"]="Ora in cui inizia il servizio notturno (può proseguire oltre la mezzanotte).", ["opt.NightEnd.L"]="Fine notte", ["opt.NightEnd.D"]="Ora in cui termina il servizio notturno.", ["opt.Enabled.L"]="Abilita TransitTimetables", ["opt.Enabled.D"]="Interruttore principale dell'intera mod. Disattivato = comportamento originale esatto: ogni linea smette di essere gestita (gli autobus eventualmente trattenuti vengono rilasciati e il conteggio della flotta e il fattore di riduzione degli ammassamenti applicati dalla mod vengono ripristinati), mentre gli orari delle singole linee vengono conservati così che riabilitandola riprendano. Attivato per impostazione predefinita.", ["grp.GroupWindows"]="Fasce di picco", ["grp.GroupCompat"]="Compatibilità", ["grp.GroupStops"]="Fermate", ["grp.GroupGeneral"]="Generale", ["ui.to"]="alle", ["ui.timetable"]="ORARIO", ["ui.on"]="ATTIVO", ["ui.off"]="DISATTIVO", ["ui.ttNow"]="ora ogni {i} min · {f} veicoli", ["ui.ttNext"]="prossima: {n}", ["ui.firstDeparture"]="Prima partenza", ["ui.peakInterval"]="Picco", ["ui.offPeakInterval"]="Fuori picco", ["ui.otherHours"]="altre ore", ["ui.nightInterval"]="Notte", ["ui.customLinePeak"]="Picco personalizzato (questa linea)", ["ui.morningPeak"]="Picco mattutino", ["ui.eveningPeak"]="Picco serale", ["ui.customPeakInterval"]="Intervallo di picco personalizzato", ["ui.terminusHint"]="Seleziona una fermata per vedere le sue partenze e impostarla come capolinea di questa linea.", ["ui.noLines"]="Nessuna linea serve questa fermata.", ["ui.line"]="Linea {n}", ["ui.terminusBadge"]="capolinea", ["ui.departs"]="parte: {d}", ["ui.noDepartures"]="nessuna partenza programmata", ["ui.notTimetabled"]="senza orario", ["ui.estimatedTimes"]="stimato, non ancora misurato", ["ui.setTerminusThis"]="Imposta come capolinea", ["ui.setTerminusAll"]="Imposta come capolinea per tutte le linee qui", ["ui.setTerminusHint"]="Il capolinea ancora l'orario e la sosta dei veicoli; qui gli autobus vengono ritirati.", ["ui.buttonTooltip"]="Orari dei trasporti", ["ui.panelTitle"]="PARTENZE", ["ui.panelHint"]="Seleziona una fermata per vedere le partenze di ogni linea da essa. Per modificare l'orario di una linea, seleziona la linea — i suoi controlli si trovano nel pannello informazioni della linea.", },
                ["ja-JP"] = new Dictionary<string, string> { ["ui.noticeAsk"]="車両数をご自身で設定しますか。ほとんどの場合その必要はありません。Modに任せることで、時刻表が実態と合ったままになります。", ["opt.VehicleCounts.L"]="車両数の管理", ["opt.VehicleCounts.D"]="時刻表を設定した各路線が何両を走らせるかを、誰が決めるかです。「Modが決める」は実測した一周時間に基づいて各路線の車両数を決め、設定した運行間隔を実際に維持できるようにします。推奨設定で、特に手を加える必要はありません。「別のModが決める」は車両数にいっさい手を触れないため、車両管理専用のModと競合せずに任せられます。「路線ごとに自分で決める」では自分で両数を入力できます。設定していない路線は引き続きModが決めます。発車時刻までの待機動作は三つとも同じです。", ["enum.VehicleCounts.ModManages"]="Modが決める", ["enum.VehicleCounts.OtherModManages"]="別のModが決める", ["enum.VehicleCounts.PlayerManages"]="路線ごとに自分で決める", ["ui.noticeTitle"]="車両数が変わります", ["ui.noticeBody"]="このModは、路線の一周に実際どれだけかかるかを計測して車両数を決めます。ゲーム内の所要時間の推定値はそれより大幅に短いため、推定値をもとに決めた路線は、設定した運行間隔に必要な数より少ない車両で運行されます。実測に基づくということは、推定値の場合より車両が増えるということです。車両の運行に費用はかかりませんが、車庫ごとの収容数はおよそ10両です。車両不足の警告に注意してください。ある路線が想定より多くを必要とする場合は、その路線の運行間隔を広げてください。", ["ui.noticeWhere"]="この設定はオプションの「車両数の管理」でいつでも変更できます。", ["ui.noticeKeep"]="いいえ、Modに任せる", ["ui.noticeOff"]="はい、自分で設定する", ["opt.StopAtEveryStop.L"]="すべての停留所で停車（空の停留所でも）", ["opt.StopAtEveryStop.D"]="デフォルトでは、Cities: Skylines II は待っている人も降りる人もいない停留所をバスがスキップすることを許可しています。減速して通過するだけなので、その停留所では予定の発車時刻まで待機せず、バスが時刻表より先行して運行してしまいます。この設定に関わらず、終点は常に停車が強制されるようになりました（スキップすると時刻表全体が破綻するため）。これをオンにすると、時刻表のある路線のすべての停留所でバスが必ず停車するようになり、掲示されたすべての時刻が守られます。ただし空の停留所ごとに短い停車時間が発生するため、路線の運行はやや遅くなります。バスなどの道路車両にのみ影響します。列車、トラム、船舶、航空機はすでにすべての駅で停車します。デフォルトはオフです。", ["opt.RealisticTripsCompat.L"]="Realistic Trips / 低速時間との互換性 — RT や Time2Work を使用する場合はオンに（ALPHA）", ["opt.RealisticTripsCompat.D"]="デフォルトはオフです。ゲーム内の1日を長くするMod（Time2Work / \"Realistic Trips\" など）を使用していない限り、オフのままにしてください。そのようなModと併用してこれをオンにすると、発車時刻・停留所時刻・車両数が先行せず正しく保たれます。Modが実際の1日の長さを自動的に計測します。低速時間Modがなければこの設定は何もせず、この設定がオフのときにModがそれを検出した場合はログに記録します。注意: この互換パスはALPHAであり、Realistic Trips とのゲーム内での動作検証はまだ行われていません。おかしな点があれば報告してください。Realistic Trips 使用時、路線は以前より正しく少ない車両数で運行されます。", ["opt.MorningPeakStart.L"]="朝ピークの開始", ["opt.MorningPeakStart.D"]="朝ピークの運行水準が始まる時刻。", ["opt.MorningPeakEnd.L"]="朝ピークの終了", ["opt.MorningPeakEnd.D"]="朝ピークの運行水準が終わる時刻。", ["opt.EveningPeakStart.L"]="夕ピークの開始", ["opt.EveningPeakStart.D"]="夕ピークの運行水準が始まる時刻。", ["opt.EveningPeakEnd.L"]="夕ピークの終了", ["opt.EveningPeakEnd.D"]="夕ピークの運行水準が終わる時刻。", ["opt.NightStart.L"]="夜間の開始", ["opt.NightStart.D"]="夜間運行が始まる時刻（深夜0時をまたぐ場合があります）。", ["opt.NightEnd.L"]="夜間の終了", ["opt.NightEnd.D"]="夜間運行が終わる時刻。", ["opt.Enabled.L"]="TransitTimetables を有効化", ["opt.Enabled.D"]="Mod全体のマスタースイッチ。オフ = 完全にバニラ状態: すべての路線の管理が停止し（待機中のバスは解放され、Modが適用した車両数と分散係数は元に戻ります）、路線ごとの時刻表は保持されるため再有効化すれば再開されます。デフォルトはオンです。", ["grp.GroupWindows"]="ピーク時間帯", ["grp.GroupCompat"]="互換性", ["grp.GroupStops"]="停留所", ["grp.GroupGeneral"]="全般", ["ui.to"]="〜", ["ui.timetable"]="時刻表", ["ui.on"]="オン", ["ui.off"]="オフ", ["ui.ttNow"]="現在 {i}分間隔 · {f}台", ["ui.ttNext"]="次: {n}", ["ui.firstDeparture"]="始発", ["ui.peakInterval"]="ピーク", ["ui.offPeakInterval"]="オフピーク", ["ui.otherHours"]="その他の時間帯", ["ui.nightInterval"]="夜間", ["ui.customLinePeak"]="カスタムピーク（この路線）", ["ui.morningPeak"]="朝ピーク", ["ui.eveningPeak"]="夕ピーク", ["ui.customPeakInterval"]="カスタムピーク間隔", ["ui.terminusHint"]="停留所を選択すると発車時刻が表示され、その停留所をこの路線の終点に設定できます。", ["ui.noLines"]="この停留所を通る路線はありません。", ["ui.line"]="路線 {n}", ["ui.terminusBadge"]="終点", ["ui.departs"]="発車: {d}", ["ui.noDepartures"]="発車予定なし", ["ui.notTimetabled"]="時刻表なし", ["ui.estimatedTimes"]="推定値（未計測）", ["ui.setTerminusThis"]="終点に設定", ["ui.setTerminusAll"]="ここのすべての路線の終点に設定", ["ui.setTerminusHint"]="終点は時刻表と車両の待機を固定します。バスはここで退役します。", ["ui.buttonTooltip"]="Transit Timetables", ["ui.panelTitle"]="発車", ["ui.panelHint"]="停留所を選択すると、その停留所からの全路線の発車時刻が表示されます。路線の時刻表を編集するには路線を選択してください。操作項目は路線の情報パネルにあります。", },
                ["ko-KR"] = new Dictionary<string, string> { ["ui.noticeAsk"]="차량 수를 직접 설정하시겠습니까? 대부분은 그럴 필요가 없습니다. 모드에 맡겨야 시간표가 실제와 맞습니다.", ["opt.VehicleCounts.L"]="차량 수 관리", ["opt.VehicleCounts.D"]="시간표가 설정된 각 노선이 몇 대의 차량을 운행할지 누가 결정할지 정합니다. \"모드가 결정\"은 실제로 측정한 순환 시간을 기준으로 각 노선의 차량 수를 정해, 설정한 배차 간격을 실제로 지킬 수 있게 합니다. 권장 설정이며 따로 신경 쓸 필요가 없습니다. \"다른 모드가 결정\"은 차량 수에 전혀 관여하지 않으므로, 차량 관리 전용 모드가 충돌 없이 담당할 수 있습니다. \"노선별로 직접 결정\"은 직접 대수를 입력할 수 있으며, 설정하지 않은 노선은 계속 모드가 정합니다. 출발 대기 동작은 세 경우 모두 동일합니다.", ["enum.VehicleCounts.ModManages"]="모드가 결정", ["enum.VehicleCounts.OtherModManages"]="다른 모드가 결정", ["enum.VehicleCounts.PlayerManages"]="노선별로 직접 결정", ["ui.noticeTitle"]="차량 수가 변경됩니다", ["ui.noticeBody"]="이 모드는 노선의 순환에 실제로 얼마나 걸리는지 측정해 차량 수를 정합니다. 게임 자체의 이동 시간 추정치는 그보다 훨씬 짧아서, 추정치로 정한 노선은 설정한 배차 간격에 필요한 것보다 적은 차량으로 운행됩니다. 실제로 측정한다는 것은 추정치보다 차량이 늘어난다는 뜻입니다. 차량 운행에는 비용이 들지 않지만 차고지 한 곳에 약 10대만 수용되므로 차량 부족 경고를 주의하세요. 어떤 노선이 원하는 것보다 많이 요구한다면 그 노선의 배차 간격을 늘리세요.", ["ui.noticeWhere"]="이 설정은 옵션의 \"차량 수 관리\"에서 언제든지 변경할 수 있습니다.", ["ui.noticeKeep"]="아니요, 모드에 맡깁니다", ["ui.noticeOff"]="예, 직접 설정합니다", ["opt.StopAtEveryStop.L"]="모든 정류장에 정차 (빈 정류장 포함)", ["opt.StopAtEveryStop.D"]="기본적으로 Cities: Skylines II는 기다리는 사람도, 내리려는 사람도 없는 정류장을 버스가 건너뛰도록 허용합니다 — 감속하며 통과만 하므로 그 정류장은 예정된 출발 시각까지 대기하지 않고, 버스가 시간표보다 앞서 운행할 수 있습니다. 이제 종점은 이 설정과 관계없이 항상 정차하도록 강제됩니다 (건너뛰면 전체 시간표가 어긋납니다). 이 옵션을 켜면 시간표가 적용된 노선의 모든 정류장에 버스가 진입하여 정차하도록 강제하므로 게시된 모든 시각이 지켜집니다 — 빈 정류장마다 잠시 정차하는 대가로 노선이 조금 느려집니다. 버스와 기타 도로 차량에만 영향을 주며, 기차·트램·선박·항공기는 이미 모든 역에 정차합니다. 기본값은 꺼짐입니다.", ["opt.RealisticTripsCompat.L"]="Realistic Trips / 느린 시간 호환 — RT나 Time2Work을 사용하면 켜세요 (알파)", ["opt.RealisticTripsCompat.D"]="기본값은 꺼짐 — 게임 내 하루 길이를 늘리는 모드(Time2Work / \"Realistic Trips\" 등)를 사용하지 않는 한 꺼진 채로 두세요. 그런 모드와 함께 이 옵션을 켜면 출발 시각, 정류장 시각, 차량 대수가 앞서 운행하지 않고 정확하게 유지됩니다. 모드가 실제 하루 길이를 자동으로 측정합니다. 느린 시간 모드가 없으면 이 설정은 아무 효과가 없으며, 이 옵션이 꺼진 상태에서 그런 모드가 감지되면 로그에 기록됩니다. 참고: 이 호환 경로는 알파이며 아직 게임 내에서 Realistic Trips와 함께 테스트되지 않았습니다 — 이상한 점이 있으면 제보해 주세요. Realistic Trips에서는 노선이 이전보다 올바르게 더 적은 차량을 사용합니다.", ["opt.MorningPeakStart.L"]="오전 첨두 시작", ["opt.MorningPeakStart.D"]="오전 첨두 운행 수준이 시작되는 시각입니다.", ["opt.MorningPeakEnd.L"]="오전 첨두 종료", ["opt.MorningPeakEnd.D"]="오전 첨두 운행 수준이 끝나는 시각입니다.", ["opt.EveningPeakStart.L"]="오후 첨두 시작", ["opt.EveningPeakStart.D"]="오후 첨두 운행 수준이 시작되는 시각입니다.", ["opt.EveningPeakEnd.L"]="오후 첨두 종료", ["opt.EveningPeakEnd.D"]="오후 첨두 운행 수준이 끝나는 시각입니다.", ["opt.NightStart.L"]="야간 시작", ["opt.NightStart.D"]="야간 운행이 시작되는 시각입니다 (자정을 넘길 수 있음).", ["opt.NightEnd.L"]="야간 종료", ["opt.NightEnd.D"]="야간 운행이 끝나는 시각입니다.", ["opt.Enabled.L"]="TransitTimetables 활성화", ["opt.Enabled.D"]="모드 전체의 주 스위치입니다. 꺼짐 = 완전한 기본 게임: 모든 노선의 관리가 중단되고(대기 중이던 버스는 해제되며 모드가 적용한 차량 대수와 뭉침 방지 계수가 되돌려집니다), 다시 켜면 이어갈 수 있도록 노선별 시간표는 유지됩니다. 기본값은 켜짐입니다.", ["grp.GroupWindows"]="첨두 시간대", ["grp.GroupCompat"]="호환성", ["grp.GroupStops"]="정류장", ["grp.GroupGeneral"]="일반", ["ui.to"]="~", ["ui.timetable"]="시간표", ["ui.on"]="켜짐", ["ui.off"]="꺼짐", ["ui.ttNow"]="현재 {i}분 간격 · 차량 {f}대", ["ui.ttNext"]="다음: {n}", ["ui.firstDeparture"]="첫차 출발", ["ui.peakInterval"]="첨두", ["ui.offPeakInterval"]="비첨두", ["ui.otherHours"]="그 외 시간", ["ui.nightInterval"]="야간", ["ui.customLinePeak"]="사용자 지정 첨두 (이 노선)", ["ui.morningPeak"]="오전 첨두", ["ui.eveningPeak"]="오후 첨두", ["ui.customPeakInterval"]="사용자 지정 첨두 간격", ["ui.terminusHint"]="정류장을 선택하면 출발 시각을 확인하고 이 노선의 종점으로 설정할 수 있습니다.", ["ui.noLines"]="이 정류장을 지나는 노선이 없습니다.", ["ui.line"]="{n}번 노선", ["ui.terminusBadge"]="종점", ["ui.departs"]="출발: {d}", ["ui.noDepartures"]="예정된 출발 없음", ["ui.notTimetabled"]="시간표 미설정", ["ui.estimatedTimes"]="추정치, 아직 측정되지 않음", ["ui.setTerminusThis"]="종점으로 설정", ["ui.setTerminusAll"]="여기의 모든 노선을 종점으로 설정", ["ui.setTerminusHint"]="종점은 시간표와 차량 대기의 기준점이며, 버스는 이곳에서 퇴역합니다.", ["ui.buttonTooltip"]="Transit Timetables", ["ui.panelTitle"]="출발 시각", ["ui.panelHint"]="정류장을 선택하면 그 정류장의 모든 노선 출발 시각을 볼 수 있습니다. 노선의 시간표를 편집하려면 노선을 선택하세요 — 관련 설정은 노선의 정보 패널에 있습니다.", },
                ["pl-PL"] = new Dictionary<string, string> { ["ui.noticeAsk"]="Wolisz samodzielnie ustawiać liczbę pojazdów? Większość graczy nie powinna: pozostawienie tego modowi sprawia, że rozkład pozostaje wiarygodny.", ["opt.VehicleCounts.L"]="Zarządzanie liczbą pojazdów", ["opt.VehicleCounts.D"]="Kto decyduje, ile pojazdów kursuje na każdej linii z rozkładem. \"Decyduje mod\" dobiera liczbę pojazdów na podstawie zmierzonego czasu pełnej pętli, aby linia mogła faktycznie utrzymać ustawiony odstęp; to ustawienie zalecane i nie wymaga uwagi. \"Decyduje inny mod\" w ogóle nie rusza liczby pojazdów, dzięki czemu dedykowany mod flotowy może nią zarządzać bez konfliktu. \"Decyduję sam, dla każdej linii\" pozwala wpisać liczby samodzielnie; linie, których nie ustawisz, nadal dobiera mod. Wstrzymywanie odjazdów działa tak samo we wszystkich trzech przypadkach.", ["enum.VehicleCounts.ModManages"]="Decyduje mod", ["enum.VehicleCounts.OtherModManages"]="Decyduje inny mod", ["enum.VehicleCounts.PlayerManages"]="Decyduję sam, dla każdej linii", ["ui.noticeTitle"]="Liczba pojazdów się zmienia", ["ui.noticeBody"]="Ten mod dobiera liczbę pojazdów, mierząc, ile naprawdę trwa pełna pętla linii. Szacunek czasu przejazdu z samej gry jest znacznie krótszy, więc linia dobrana według szacunku kursuje z mniejszą liczbą pojazdów, niż wymaga wybrany odstęp. Rzeczywisty pomiar oznacza więc więcej pojazdów, niż dałby szacunek. Ich utrzymanie nic nie kosztuje, ale jedna zajezdnia mieści około dziesięciu, więc zwracaj uwagę na ostrzeżenia o braku pojazdów. Jeśli linia potrzebuje więcej, niż chcesz, zwiększ jej odstęp.", ["ui.noticeWhere"]="Możesz to zmienić w dowolnej chwili w Opcjach, w sekcji \"Zarządzanie liczbą pojazdów\".", ["ui.noticeKeep"]="Nie, niech zarządza mod", ["ui.noticeOff"]="Tak, zajmę się tym sam", ["opt.StopAtEveryStop.L"]="Zatrzymuj na każdym przystanku (nawet pustym)", ["opt.StopAtEveryStop.D"]="Domyślnie Cities: Skylines II pozwala autobusowi POMINĄĆ przystanek, na którym nikt nie czeka i nikt nie chce wysiąść — jedynie zwalnia i przejeżdża, więc taki przystanek nigdy nie jest wstrzymywany do planowego odjazdu i autobus może wyprzedzić swój rozkład jazdy. Przystanek krańcowy jest teraz zawsze zmuszony do zatrzymania, niezależnie od tego ustawienia (jego pominięcie rozstroiłoby cały rozkład). Włącz tę opcję, aby zmusić autobusy do zatrzymania się na KAŻDYM przystanku linii z rozkładem jazdy, tak by każda podana godzina była dotrzymana — kosztem krótkiego postoju na każdym pustym przystanku, przez co linie kursują nieco wolniej. Dotyczy wyłącznie autobusów i innych pojazdów drogowych; pociągi, tramwaje, statki i samoloty i tak zatrzymują się na każdej stacji. Domyślnie wyłączone.", ["opt.RealisticTripsCompat.L"]="Zgodność z Realistic Trips / spowolnionym czasem — włącz, jeśli używasz RT lub Time2Work (ALPHA)", ["opt.RealisticTripsCompat.D"]="Domyślnie wyłączone — zostaw wyłączone, chyba że używasz moda wydłużającego dobę w grze (Time2Work / \"Realistic Trips\" lub podobnego). Włącz z takim modem, a odjazdy, godziny na przystankach i wielkości taboru pozostaną poprawne zamiast kursować przed czasem; mod automatycznie mierzy rzeczywistą długość doby. Bez moda spowalniającego czas to ustawienie nic nie robi, a jeśli mod wykryje taki mod, gdy ta opcja jest wyłączona, odnotuje to w dzienniku. UWAGA: ta ścieżka zgodności jest w wersji ALPHA i NIE została jeszcze przetestowana z Realistic Trips w grze — zgłaszaj wszelkie nieprawidłowości. Pod Realistic Trips twoje linie będą poprawnie używać mniej pojazdów niż wcześniej.", ["opt.MorningPeakStart.L"]="Początek porannego szczytu", ["opt.MorningPeakStart.D"]="Godzina, o której zaczyna się poranny poziom obsługi szczytowej.", ["opt.MorningPeakEnd.L"]="Koniec porannego szczytu", ["opt.MorningPeakEnd.D"]="Godzina, o której kończy się poranny poziom obsługi szczytowej.", ["opt.EveningPeakStart.L"]="Początek wieczornego szczytu", ["opt.EveningPeakStart.D"]="Godzina, o której zaczyna się wieczorny poziom obsługi szczytowej.", ["opt.EveningPeakEnd.L"]="Koniec wieczornego szczytu", ["opt.EveningPeakEnd.D"]="Godzina, o której kończy się wieczorny poziom obsługi szczytowej.", ["opt.NightStart.L"]="Początek nocy", ["opt.NightStart.D"]="Godzina, o której zaczyna się obsługa nocna (może przekraczać północ).", ["opt.NightEnd.L"]="Koniec nocy", ["opt.NightEnd.D"]="Godzina, o której kończy się obsługa nocna.", ["opt.Enabled.L"]="Włącz TransitTimetables", ["opt.Enabled.D"]="Główny przełącznik całego moda. Wyłączony = dokładnie jak w grze podstawowej: każda linia przestaje być zarządzana (wszystkie wstrzymane autobusy są zwalniane, a zastosowana przez mod liczba pojazdów i współczynnik rozgęszczania zostają cofnięte), przy czym twoje rozkłady jazdy poszczególnych linii są zachowane, aby ponowne włączenie je wznowiło. Domyślnie włączony.", ["grp.GroupWindows"]="Okna szczytu", ["grp.GroupCompat"]="Zgodność", ["grp.GroupStops"]="Przystanki", ["grp.GroupGeneral"]="Ogólne", ["ui.to"]="do", ["ui.timetable"]="ROZKŁAD JAZDY", ["ui.on"]="WŁ.", ["ui.off"]="WYŁ.", ["ui.ttNow"]="teraz co {i} min · {f} pojazdów", ["ui.ttNext"]="następny: {n}", ["ui.firstDeparture"]="Pierwszy odjazd", ["ui.peakInterval"]="Szczyt", ["ui.offPeakInterval"]="Poza szczytem", ["ui.otherHours"]="pozostałe godziny", ["ui.nightInterval"]="Noc", ["ui.customLinePeak"]="Własny szczyt (ta linia)", ["ui.morningPeak"]="Poranny szczyt", ["ui.eveningPeak"]="Wieczorny szczyt", ["ui.customPeakInterval"]="Własny odstęp w szczycie", ["ui.terminusHint"]="Wybierz przystanek, aby zobaczyć jego odjazdy i ustawić go jako przystanek krańcowy tej linii.", ["ui.noLines"]="Żadna linia nie obsługuje tego przystanku.", ["ui.line"]="Linia {n}", ["ui.terminusBadge"]="krańcowy", ["ui.departs"]="odjazd: {d}", ["ui.noDepartures"]="brak zaplanowanych odjazdów", ["ui.notTimetabled"]="brak rozkładu jazdy", ["ui.estimatedTimes"]="szacowane, jeszcze niezmierzone", ["ui.setTerminusThis"]="Ustaw jako krańcowy", ["ui.setTerminusAll"]="Ustaw jako krańcowy dla wszystkich linii tutaj", ["ui.setTerminusHint"]="Przystanek krańcowy wyznacza rozkład jazdy i wstrzymanie pojazdów; autobusy są tu wycofywane.", ["ui.buttonTooltip"]="Rozkłady jazdy komunikacji", ["ui.panelTitle"]="ODJAZDY", ["ui.panelHint"]="Wybierz przystanek, aby zobaczyć odjazdy wszystkich linii z tego miejsca. Aby edytować rozkład jazdy linii, wybierz linię — jej ustawienia znajdują się w panelu informacyjnym linii.", },
                ["pt-BR"] = new Dictionary<string, string> { ["ui.noticeAsk"]="Prefere definir o número de veículos você mesmo? A maioria não precisa: deixar o mod cuidar disso é o que mantém o horário confiável.", ["opt.VehicleCounts.L"]="Gerenciamento do número de veículos", ["opt.VehicleCounts.D"]="Quem decide quantos veículos cada linha com horário opera. \"O mod decide\" dimensiona cada linha pelo tempo de volta medido, para que ela consiga realmente manter o intervalo definido; é a opção recomendada e não exige atenção. \"Outro mod decide\" não mexe no número de veículos, permitindo que um mod dedicado a frotas cuide disso sem conflito. \"Eu decido, por linha\" permite que você mesmo informe as quantidades; qualquer linha que você não configurar continua sendo dimensionada pelo mod. As esperas de partida funcionam igual nos três casos.", ["enum.VehicleCounts.ModManages"]="O mod decide", ["enum.VehicleCounts.OtherModManages"]="Outro mod decide", ["enum.VehicleCounts.PlayerManages"]="Eu decido, por linha", ["ui.noticeTitle"]="O número de veículos vai mudar", ["ui.noticeBody"]="Este mod dimensiona cada linha medindo quanto tempo o percurso realmente leva. A estimativa de tempo de viagem do próprio jogo fica bem abaixo disso, então uma linha dimensionada pela estimativa roda com menos veículos do que o intervalo escolhido exige. Medir de verdade significa mais veículos do que a estimativa daria. Eles não custam nada para operar, mas cada garagem comporta cerca de dez, então fique atento aos avisos de veículos insuficientes. Se uma linha pedir mais do que você quer, aumente o intervalo dela.", ["ui.noticeWhere"]="Você pode mudar isso a qualquer momento nas Opções, em \"Gerenciamento do número de veículos\".", ["ui.noticeKeep"]="Não, deixe o mod gerenciar", ["ui.noticeOff"]="Sim, eu vou gerenciar", ["opt.StopAtEveryStop.L"]="Parar em cada parada (mesmo nas vazias)", ["opt.StopAtEveryStop.D"]="Por padrão, Cities: Skylines II permite que um ônibus PULE uma parada onde ninguém está esperando e ninguém quer descer — ele apenas desacelera e passa, então essa parada nunca é retida até o horário programado de partida e o ônibus pode adiantar-se à sua tabela de horários. O terminal agora é sempre forçado a parar, independentemente desta configuração (pulá-lo desmontaria toda a programação). Ative esta opção para forçar os ônibus a encostar e parar em CADA parada de uma linha com tabela de horários, para que cada horário exibido seja cumprido — ao custo de uma breve espera em cada parada vazia, o que deixa as linhas um pouco mais lentas. Afeta apenas ônibus e outros veículos rodoviários; trens, bondes, navios e aeronaves já param em todas as estações. Desativado por padrão.", ["opt.RealisticTripsCompat.L"]="Compatibilidade com Realistic Trips / tempo lento — ative se você usa RT ou Time2Work (ALFA)", ["opt.RealisticTripsCompat.D"]="Desativado por padrão — deixe desativado a menos que você use um mod que alongue o dia do jogo (Time2Work / \"Realistic Trips\" ou similar). Ative-o com um mod desses e as partidas, horários de parada e tamanhos de frota permanecem corretos em vez de rodar adiantados; o mod mede automaticamente a duração real do dia. Sem um mod de tempo lento esta configuração não faz nada, e se o mod detectar um enquanto isto estiver desativado ele registrará no log. NOTA: este caminho de compatibilidade é ALFA e ainda NÃO foi testado com o Realistic Trips em jogo — por favor, relate qualquer coisa estranha. Sob o Realistic Trips suas linhas usarão corretamente menos veículos do que antes.", ["opt.MorningPeakStart.L"]="Início do pico da manhã", ["opt.MorningPeakStart.D"]="Hora em que começa o nível de serviço do pico da manhã.", ["opt.MorningPeakEnd.L"]="Fim do pico da manhã", ["opt.MorningPeakEnd.D"]="Hora em que termina o nível de serviço do pico da manhã.", ["opt.EveningPeakStart.L"]="Início do pico da noite", ["opt.EveningPeakStart.D"]="Hora em que começa o nível de serviço do pico da noite.", ["opt.EveningPeakEnd.L"]="Fim do pico da noite", ["opt.EveningPeakEnd.D"]="Hora em que termina o nível de serviço do pico da noite.", ["opt.NightStart.L"]="Início da madrugada", ["opt.NightStart.D"]="Hora em que começa o serviço noturno (pode passar da meia-noite).", ["opt.NightEnd.L"]="Fim da madrugada", ["opt.NightEnd.D"]="Hora em que termina o serviço noturno.", ["opt.Enabled.L"]="Ativar TransitTimetables", ["opt.Enabled.D"]="Interruptor mestre de todo o mod. Desativado = jogo original exato: todas as linhas deixam de ser gerenciadas (qualquer ônibus retido é liberado e a contagem de frota e o fator de dispersão aplicados pelo mod são revertidos), enquanto suas tabelas de horários por linha são mantidas para que reativar as retome. Ativado por padrão.", ["grp.GroupWindows"]="Janelas de pico", ["grp.GroupCompat"]="Compatibilidade", ["grp.GroupStops"]="Paradas", ["grp.GroupGeneral"]="Geral", ["ui.to"]="às", ["ui.timetable"]="TABELA DE HORÁRIOS", ["ui.on"]="LIGADO", ["ui.off"]="DESLIGADO", ["ui.ttNow"]="agora a cada {i} min · {f} veículos", ["ui.ttNext"]="próxima: {n}", ["ui.firstDeparture"]="Primeira partida", ["ui.peakInterval"]="Pico", ["ui.offPeakInterval"]="Fora de pico", ["ui.otherHours"]="outros horários", ["ui.nightInterval"]="Madrugada", ["ui.customLinePeak"]="Pico personalizado (esta linha)", ["ui.morningPeak"]="Pico da manhã", ["ui.eveningPeak"]="Pico da noite", ["ui.customPeakInterval"]="Intervalo de pico personalizado", ["ui.terminusHint"]="Selecione uma parada para ver suas partidas e defini-la como o terminal desta linha.", ["ui.noLines"]="Nenhuma linha atende esta parada.", ["ui.line"]="Linha {n}", ["ui.terminusBadge"]="terminal", ["ui.departs"]="parte: {d}", ["ui.noDepartures"]="nenhuma partida programada", ["ui.notTimetabled"]="sem tabela de horários", ["ui.estimatedTimes"]="estimado, ainda não medido", ["ui.setTerminusThis"]="Definir como terminal", ["ui.setTerminusAll"]="Definir como terminal para todas as linhas aqui", ["ui.setTerminusHint"]="O terminal ancora a programação e a retenção de veículos; os ônibus se aposentam aqui.", ["ui.buttonTooltip"]="Tabelas de Horários do Transporte", ["ui.panelTitle"]="PARTIDAS", ["ui.panelHint"]="Selecione uma parada para ver as partidas de todas as linhas a partir dela. Para editar a tabela de horários de uma linha, selecione a linha — seus controles estão no painel de informações da linha.", },
                ["ru-RU"] = new Dictionary<string, string> { ["ui.noticeAsk"]="Хотите задавать количество машин самостоятельно? Большинству это не нужно: именно управление модом сохраняет расписание достоверным.", ["opt.VehicleCounts.L"]="Управление количеством транспорта", ["opt.VehicleCounts.D"]="Кто определяет, сколько машин работает на каждой линии с расписанием. \"Решает мод\" подбирает количество по измеренному времени полного круга, чтобы линия действительно выдерживала заданный интервал; это рекомендуемый вариант, он не требует внимания. \"Решает другой мод\" вообще не трогает количество машин, поэтому специализированный мод может управлять им без конфликта. \"Решаю я, для каждой линии\" позволяет ввести числа самостоятельно; линии, которые вы не настроили, по-прежнему рассчитывает мод. Задержка отправления работает одинаково во всех трёх случаях.", ["enum.VehicleCounts.ModManages"]="Решает мод", ["enum.VehicleCounts.OtherModManages"]="Решает другой мод", ["enum.VehicleCounts.PlayerManages"]="Решаю я, для каждой линии", ["ui.noticeTitle"]="Количество транспорта изменится", ["ui.noticeBody"]="Этот мод подбирает количество машин, измеряя, сколько на самом деле занимает круг линии. Игровая оценка времени в пути заметно меньше, поэтому линия, рассчитанная по оценке, работает с меньшим числом машин, чем требует выбранный интервал. Реальное измерение означает больше машин, чем дала бы оценка. Их работа ничего не стоит, но в одном депо помещается около десяти, поэтому следите за предупреждениями о нехватке транспорта. Если линия требует больше, чем вам хотелось бы, увеличьте её интервал.", ["ui.noticeWhere"]="Это можно изменить в любой момент в настройках, в разделе \"Управление количеством транспорта\".", ["ui.noticeKeep"]="Нет, пусть управляет мод", ["ui.noticeOff"]="Да, я буду управлять сам", ["opt.StopAtEveryStop.L"]="Останавливаться на каждой остановке (даже пустой)", ["opt.StopAtEveryStop.D"]="По умолчанию Cities: Skylines II позволяет автобусу ПРОПУСТИТЬ остановку, где никто не ждёт и никто не хочет выйти — он лишь притормаживает и проезжает, поэтому такая остановка никогда не удерживается до запланированного отправления, и автобус может идти с опережением расписания. Конечная станция теперь всегда принудительно требует остановки независимо от этого параметра (её пропуск сорвал бы всё расписание). Включите этот параметр, чтобы автобусы заезжали и останавливались на КАЖДОЙ остановке маршрута с расписанием, чтобы каждое указанное время соблюдалось — ценой короткой стоянки на каждой пустой остановке, из-за чего маршруты идут чуть медленнее. Затрагивает только автобусы и другой дорожный транспорт; поезда, трамваи, суда и самолёты и так останавливаются на каждой станции. По умолчанию ВЫКЛ.", ["opt.RealisticTripsCompat.L"]="Совместимость с Realistic Trips / замедлением времени — включите, если используете RT или Time2Work (АЛЬФА)", ["opt.RealisticTripsCompat.D"]="По умолчанию ВЫКЛ — оставьте выключенным, если только вы не используете мод, удлиняющий игровой день (Time2Work / \\\"Realistic Trips\\\" или подобный). Включите его вместе с таким модом, и отправления, время на остановках и размеры парка останутся корректными вместо опережения; мод автоматически замеряет реальную длину дня. Без мода замедления времени этот параметр ничего не делает, а если мод обнаружит такой при выключенном параметре, он отметит это в журнале. ПРИМЕЧАНИЕ: этот путь совместимости — АЛЬФА и пока НЕ тестировался с Realistic Trips в игре — сообщайте обо всём странном. При Realistic Trips ваши маршруты будут корректно использовать меньше транспорта, чем раньше.", ["opt.MorningPeakStart.L"]="Начало утреннего часа пик", ["opt.MorningPeakStart.D"]="Час, когда начинается уровень обслуживания утреннего часа пик.", ["opt.MorningPeakEnd.L"]="Конец утреннего часа пик", ["opt.MorningPeakEnd.D"]="Час, когда заканчивается уровень обслуживания утреннего часа пик.", ["opt.EveningPeakStart.L"]="Начало вечернего часа пик", ["opt.EveningPeakStart.D"]="Час, когда начинается уровень обслуживания вечернего часа пик.", ["opt.EveningPeakEnd.L"]="Конец вечернего часа пик", ["opt.EveningPeakEnd.D"]="Час, когда заканчивается уровень обслуживания вечернего часа пик.", ["opt.NightStart.L"]="Начало ночи", ["opt.NightStart.D"]="Час, когда начинается ночное обслуживание (может переходить за полночь).", ["opt.NightEnd.L"]="Конец ночи", ["opt.NightEnd.D"]="Час, когда заканчивается ночное обслуживание.", ["opt.Enabled.L"]="Включить TransitTimetables", ["opt.Enabled.D"]="Главный переключатель всего мода. Выкл = точно как в оригинале: все маршруты перестают управляться (любые удержанные автобусы отпускаются, а заданные модом количество транспорта и коэффициент разгруппировки возвращаются к исходным), при этом ваши расписания по маршрутам сохраняются, так что повторное включение их возобновит. По умолчанию ВКЛ.", ["grp.GroupWindows"]="Окна часа пик", ["grp.GroupCompat"]="Совместимость", ["grp.GroupStops"]="Остановки", ["grp.GroupGeneral"]="Общие", ["ui.to"]="до", ["ui.timetable"]="РАСПИСАНИЕ", ["ui.on"]="ВКЛ", ["ui.off"]="ВЫКЛ", ["ui.ttNow"]="сейчас каждые {i} мин · {f} ед. транспорта", ["ui.ttNext"]="далее: {n}", ["ui.firstDeparture"]="Первое отправление", ["ui.peakInterval"]="Час пик", ["ui.offPeakInterval"]="Вне часа пик", ["ui.otherHours"]="прочие часы", ["ui.nightInterval"]="Ночь", ["ui.customLinePeak"]="Свой час пик (этот маршрут)", ["ui.morningPeak"]="Утренний час пик", ["ui.eveningPeak"]="Вечерний час пик", ["ui.customPeakInterval"]="Свой интервал в час пик", ["ui.terminusHint"]="Выберите остановку, чтобы увидеть её отправления и назначить её конечной станцией этого маршрута.", ["ui.noLines"]="Эту остановку не обслуживают маршруты.", ["ui.line"]="Маршрут {n}", ["ui.terminusBadge"]="конечная", ["ui.departs"]="отправление: {d}", ["ui.noDepartures"]="отправления не запланированы", ["ui.notTimetabled"]="без расписания", ["ui.estimatedTimes"]="оценка, ещё не измерено", ["ui.setTerminusThis"]="Назначить конечной", ["ui.setTerminusAll"]="Назначить конечной для всех маршрутов здесь", ["ui.setTerminusHint"]="Конечная станция закрепляет расписание и удержание транспорта; здесь автобусы выводятся из эксплуатации.", ["ui.buttonTooltip"]="Расписания транспорта", ["ui.panelTitle"]="ОТПРАВЛЕНИЯ", ["ui.panelHint"]="Выберите остановку, чтобы увидеть отправления всех маршрутов от неё. Чтобы изменить расписание маршрута, выберите маршрут — его настройки находятся в информационной панели маршрута.", },
                ["zh-HANS"] = new Dictionary<string, string> { ["ui.noticeAsk"]="你想自己设置车辆数量吗？大多数玩家不需要：交给模组处理才能让时刻表保持可靠。", ["opt.VehicleCounts.L"]="车辆数量管理", ["opt.VehicleCounts.D"]="由谁决定每条已设置时刻表的线路运行多少车辆。「由模组决定」会根据实测的一圈运行时间为每条线路配置车辆，使其真正能够维持你设定的发车间隔；这是推荐设置，无需额外关注。「由其他模组决定」完全不改动车辆数量，便于专门的车队模组接管，二者不会互相冲突。「由我按线路决定」允许你自行填写数量；你未设置的线路仍由模组配置。三种模式下的发车等待行为完全相同。", ["enum.VehicleCounts.ModManages"]="由模组决定", ["enum.VehicleCounts.OtherModManages"]="由其他模组决定", ["enum.VehicleCounts.PlayerManages"]="由我按线路决定", ["ui.noticeTitle"]="车辆数量即将变化", ["ui.noticeBody"]="本模组通过测量线路实际跑完一圈需要多久来配置车辆。游戏自身的行程时间估算远低于此，因此按估算配置的线路，其车辆数会少于所选发车间隔实际所需。改为实测，就意味着车辆会比按估算时更多。车辆运行不产生费用，但每个车场大约只能容纳十辆，请留意车辆不足的警告。如果某条线路所需的车辆超出你的预期，请调宽该线路的发车间隔。", ["ui.noticeWhere"]="你可以随时在选项中的「车辆数量管理」处更改此设置。", ["ui.noticeKeep"]="不用，交给模组管理", ["ui.noticeOff"]="是的，我自己管理", ["opt.StopAtEveryStop.L"]="每一站都停靠（即使无人的站点）", ["opt.StopAtEveryStop.D"]="默认情况下，《都市：天际线 II》允许公交车跳过既无人等候、也无人下车的站点——它只是减速驶过，因此该站点从不会被强制停靠到预定发车时间，公交车便可能提前于时刻表运行。现在无论此设置如何，终点站都始终强制停靠（跳过它会打乱整份时刻表）。开启此项可强制公交车在有时刻表的线路上驶入并停靠每一站，使每个显示的时刻都得到遵守——代价是在每个无人的站点短暂停留，使线路运行略慢一些。仅影响公交车及其他道路车辆；火车、有轨电车、船只和飞机本就在每一站停靠。默认关闭。", ["opt.RealisticTripsCompat.L"]="Realistic Trips / 慢时间兼容——若使用 RT 或 Time2Work 请开启（ALPHA）", ["opt.RealisticTripsCompat.D"]="默认关闭——除非你使用了会延长游戏内一天时长的模组（Time2Work / \"Realistic Trips\" 或类似模组），否则请保持关闭。搭配此类模组时开启，发车时间、到站时刻和车辆数量将保持正确而不会提前运行；模组会自动测量真实的一天时长。若未使用慢时间模组，此设置不起任何作用；若在此项关闭时检测到该类模组，将会在日志中记录提示。注意：此兼容路径为 ALPHA，尚未在游戏内针对 Realistic Trips 测试——如有异常请反馈。在 Realistic Trips 下，你的线路将正确地使用比以往更少的车辆。", ["opt.MorningPeakStart.L"]="早高峰开始", ["opt.MorningPeakStart.D"]="早高峰运营水平开始的时刻。", ["opt.MorningPeakEnd.L"]="早高峰结束", ["opt.MorningPeakEnd.D"]="早高峰运营水平结束的时刻。", ["opt.EveningPeakStart.L"]="晚高峰开始", ["opt.EveningPeakStart.D"]="晚高峰运营水平开始的时刻。", ["opt.EveningPeakEnd.L"]="晚高峰结束", ["opt.EveningPeakEnd.D"]="晚高峰运营水平结束的时刻。", ["opt.NightStart.L"]="夜间开始", ["opt.NightStart.D"]="夜间运营开始的时刻（可能跨过午夜）。", ["opt.NightEnd.L"]="夜间结束", ["opt.NightEnd.D"]="夜间运营结束的时刻。", ["opt.Enabled.L"]="启用 TransitTimetables", ["opt.Enabled.D"]="整个模组的总开关。关闭 = 完全原版：每条线路都不再被管理（任何被暂停的公交车都会放行，模组施加的车辆数和防聚集系数都会还原），同时保留你的各线路时刻表，以便重新启用时恢复。默认开启。", ["grp.GroupWindows"]="高峰时段", ["grp.GroupCompat"]="兼容性", ["grp.GroupStops"]="站点", ["grp.GroupGeneral"]="常规", ["ui.to"]="至", ["ui.timetable"]="时刻表", ["ui.on"]="开", ["ui.off"]="关", ["ui.ttNow"]="现每 {i} 分钟 · {f} 辆车", ["ui.ttNext"]="下一班：{n}", ["ui.firstDeparture"]="首班发车", ["ui.peakInterval"]="高峰", ["ui.offPeakInterval"]="平峰", ["ui.otherHours"]="其他时段", ["ui.nightInterval"]="夜间", ["ui.customLinePeak"]="自定义高峰（本线路）", ["ui.morningPeak"]="早高峰", ["ui.eveningPeak"]="晚高峰", ["ui.customPeakInterval"]="自定义高峰间隔", ["ui.terminusHint"]="选择一个站点以查看其发车时刻，并将其设为本线路的终点站。", ["ui.noLines"]="没有线路停靠此站点。", ["ui.line"]="线路 {n}", ["ui.terminusBadge"]="终点站", ["ui.departs"]="发车：{d}", ["ui.noDepartures"]="无预定发车", ["ui.notTimetabled"]="无时刻表", ["ui.estimatedTimes"]="预估值，尚未实测", ["ui.setTerminusThis"]="设为终点站", ["ui.setTerminusAll"]="设为此处所有线路的终点站", ["ui.setTerminusHint"]="终点站锚定时刻表和车辆暂停；公交车在此退役。", ["ui.buttonTooltip"]="公交时刻表", ["ui.panelTitle"]="发车", ["ui.panelHint"]="选择一个站点以查看每条线路从该站的发车时刻。要编辑某线路的时刻表，请选中该线路——其控件位于该线路的信息面板中。", },
                ["zh-HANT"] = new Dictionary<string, string> { ["ui.noticeAsk"]="你想自己設定車輛數量嗎？大多數玩家不需要：交給模組處理才能讓時刻表保持可靠。", ["opt.VehicleCounts.L"]="車輛數量管理", ["opt.VehicleCounts.D"]="由誰決定每條已設定時刻表的路線運行多少車輛。「由模組決定」會根據實測的一圈運行時間為每條路線配置車輛，使其真正能夠維持你設定的發車間隔；這是建議設定，無需額外關注。「由其他模組決定」完全不改動車輛數量，便於專門的車隊模組接管，兩者不會互相衝突。「由我依路線決定」允許你自行填寫數量；你未設定的路線仍由模組配置。三種模式下的發車等待行為完全相同。", ["enum.VehicleCounts.ModManages"]="由模組決定", ["enum.VehicleCounts.OtherModManages"]="由其他模組決定", ["enum.VehicleCounts.PlayerManages"]="由我依路線決定", ["ui.noticeTitle"]="車輛數量即將變化", ["ui.noticeBody"]="本模組透過測量路線實際跑完一圈需要多久來配置車輛。遊戲自身的行程時間估算遠低於此，因此依估算配置的路線，其車輛數會少於所選發車間隔實際所需。改為實測，就意味著車輛會比依估算時更多。車輛運行不會產生費用，但每個車場大約只能容納十輛，請留意車輛不足的警告。如果某條路線所需的車輛超出你的預期，請調寬該路線的發車間隔。", ["ui.noticeWhere"]="你可以隨時在選項中的「車輛數量管理」處更改此設定。", ["ui.noticeKeep"]="不用，交給模組管理", ["ui.noticeOff"]="是的，我自己管理", ["opt.StopAtEveryStop.L"]="每一站都停靠（即使空無一人）", ["opt.StopAtEveryStop.D"]="預設情況下，《Cities: Skylines II》允許公車「跳過」某個既無人等車、也無人下車的站點 —— 它只會減速滑行通過，因此該站不會被保留到其排定的發車時刻，公車便可能領先於時刻表。無論此設定為何，終點站現在一律強制停靠（跳過終點站會使整份時刻表脫節）。開啟此選項可強制公車在有時刻表路線的「每一站」都靠站停車，讓每一個張貼的時刻都被遵守 —— 代價是在每個空站短暫停留，使路線略微變慢。僅影響公車及其他道路車輛；火車、路面電車、船隻與飛機本來就每站皆停。預設為關閉。", ["opt.RealisticTripsCompat.L"]="Realistic Trips／慢速時間相容性 —— 若你使用 RT 或 Time2Work 請開啟（ALPHA）", ["opt.RealisticTripsCompat.D"]="預設為關閉 —— 除非你使用會延長遊戲內一天長度的模組（Time2Work／「Realistic Trips」或類似模組），否則請保持關閉。搭配這類模組時開啟，發車時刻、靠站時刻與車隊規模便會維持正確而不會提早運行；模組會自動實測真實的一天長度。若沒有慢速時間模組，此設定不會有任何作用；而若模組偵測到有這類模組但此設定為關閉，它會在日誌中註記。注意：此相容路徑仍為 ALPHA，尚未在遊戲中對 Realistic Trips 進行測試 —— 若有任何異常請回報。在 Realistic Trips 下，你的路線會正確地使用比以往更少的車輛。", ["opt.MorningPeakStart.L"]="早尖峰開始", ["opt.MorningPeakStart.D"]="早尖峰服務等級開始的時刻。", ["opt.MorningPeakEnd.L"]="早尖峰結束", ["opt.MorningPeakEnd.D"]="早尖峰服務等級結束的時刻。", ["opt.EveningPeakStart.L"]="晚尖峰開始", ["opt.EveningPeakStart.D"]="晚尖峰服務等級開始的時刻。", ["opt.EveningPeakEnd.L"]="晚尖峰結束", ["opt.EveningPeakEnd.D"]="晚尖峰服務等級結束的時刻。", ["opt.NightStart.L"]="夜間開始", ["opt.NightStart.D"]="夜間服務開始的時刻（可能跨越午夜）。", ["opt.NightEnd.L"]="夜間結束", ["opt.NightEnd.D"]="夜間服務結束的時刻。", ["opt.Enabled.L"]="啟用 TransitTimetables", ["opt.Enabled.D"]="整個模組的總開關。關閉＝完全回到原版：每條路線都不再受管理（任何被保留的公車會被釋放，模組套用的車輛數與去群聚係數都會還原），同時保留你的各路線時刻表，以便重新啟用時可繼續使用。預設為開啟。", ["grp.GroupWindows"]="尖峰時段", ["grp.GroupCompat"]="相容性", ["grp.GroupStops"]="站點", ["grp.GroupGeneral"]="一般", ["ui.to"]="至", ["ui.timetable"]="時刻表", ["ui.on"]="開啟", ["ui.off"]="關閉", ["ui.ttNow"]="目前每 {i} 分鐘 · {f} 輛車", ["ui.ttNext"]="下一班：{n}", ["ui.firstDeparture"]="首班發車", ["ui.peakInterval"]="尖峰", ["ui.offPeakInterval"]="離峰", ["ui.otherHours"]="其他時段", ["ui.nightInterval"]="夜間", ["ui.customLinePeak"]="自訂尖峰（此路線）", ["ui.morningPeak"]="早尖峰", ["ui.eveningPeak"]="晚尖峰", ["ui.customPeakInterval"]="自訂尖峰班距", ["ui.terminusHint"]="選擇一個站點以檢視其發車時刻，並將其設為此路線的終點站。", ["ui.noLines"]="沒有路線行經此站。", ["ui.line"]="路線 {n}", ["ui.terminusBadge"]="終點站", ["ui.departs"]="發車：{d}", ["ui.noDepartures"]="無排定發車", ["ui.notTimetabled"]="無時刻表", ["ui.estimatedTimes"]="預估值，尚未實測", ["ui.setTerminusThis"]="設為終點站", ["ui.setTerminusAll"]="設為此處所有路線的終點站", ["ui.setTerminusHint"]="終點站是時刻表與車輛保留的錨點；公車在此退役。", ["ui.buttonTooltip"]="運輸時刻表", ["ui.panelTitle"]="發車時刻", ["ui.panelHint"]="選擇一個站點以檢視每條路線由此站發車的時刻。要編輯某條路線的時刻表，請選取該路線 —— 其控制項位於該路線的資訊面板中。", },
